complexity.body:
int[] ids = {1, 2, 3, 4, 5, 6, 7, 8};
 int target = 8, linearChecks = 0;
 for (int id : ids) {
     linearChecks++;
     if (id == target) break;
 }
 int low = 0, high = ids.length - 1, binaryChecks = 0;
 while (low <= high) {
     int mid = low + (high - low) / 2;
     binaryChecks++;
     if (ids[mid] == target) break;
     if (ids[mid] < target) low = mid + 1;
     else high = mid - 1;
 }
 System.out.println("Linear checks: " + linearChecks);
 System.out.println("Binary checks: " + binaryChecks);

