String text = "([])";
 Deque<Character> stack = new ArrayDeque<>();
 boolean valid = true;
 for (char ch : text.toCharArray()) {
     if (ch == '(' || ch == '[') stack.push(ch);
     else if (ch == ')' || ch == ']') {
         if (stack.isEmpty()) { valid = false; break; }
         char open = stack.pop();
         if ((ch == ')' && open != '(') || (ch == ']' && open != '[')) {
             valid = false; break;
         }
     }
 }
 System.out.println("Balanced: " + (valid && stack.isEmpty()));

