static class CounterQueue {
     int[] items = new int[3];
     int front = 0, size = 0;
     void add(int id) {
         if (size == items.length) throw new IllegalStateException("Full");
         items[(front + size) % items.length] = id;
         size++;
     }
     int remove() {
         if (size == 0) throw new IllegalStateException("Empty");
         int id = items[front];
         front = (front + 1) % items.length;
         size--;
         return id;
     }
 }
 public static void main(String[] args) {
     CounterQueue queue = new CounterQueue();
     queue.add(101); queue.add(102);
     System.out.println("Served: " + queue.remove());
     queue.add(103);
     System.out.println("Next: " + queue.remove());
     System.out.println("Then: " + queue.remove());
 }

