int[] heap = {20, 50, 30};
 int parent = 0;
 while (2 * parent + 1 < heap.length) {
     int child = 2 * parent + 1;
     if (child + 1 < heap.length && heap[child + 1] > heap[child]) child++;
     if (heap[parent] >= heap[child]) break;
     int temp = heap[parent]; heap[parent] = heap[child]; heap[child] = temp;
     parent = child;
 }
