dynamic-programming.body:
int[] vouchers = {1, 3, 4};
 int target = 6;
 int[] dp = new int[target + 1];
 Arrays.fill(dp, target + 1);
 dp[0] = 0;
 for (int value = 1; value <= target; value++) {
     for (int voucher : vouchers) {
         if (voucher <= value) dp[value] = Math.min(dp[value], dp[value - voucher] + 1);
     }
 }
 System.out.println("Fewest vouchers: " + (dp[target] > target ? -1 : dp[target]));
